"""Literal known answers protect the independent canonical collection equations and order semantics."""
import unittest
from collections_oracle import wire,decode,encode,MAX


# Expected bytes/order are literal rather than generated by the production implementation.
class CollectionsHarness(unittest.TestCase):
    # C.1.6 set concatenation has no count; the enclosing variable operator explicitly adds one.
    def test_set_framing(self):
        self.assertEqual(wire('F','2',[255,256]),b'\xff\0\0\1')
        self.assertEqual(wire('S','2',[255,256]),b'\2\xff\0\0\1')
        self.assertEqual(decode('S','2',0,2,5,b'\2\xff\0\0\1tail'),'5 2 255,256 ff000001 02ff000001')

    # Dictionary count is the number of key/value pairs, not fields or packed bytes.
    def test_dictionary_framing(self):
        self.assertEqual(wire('M','nn',[(1,9),(2,3)]),b'\2\1\11\2\3')
        self.assertEqual(decode('M','nn',0,2,5,b'\2\1\11\2\3'),'5 2 1/9,2/3 0201090203')

    # Numeric 255<256 differs from little-endian wire lexicographic order; byte keys follow octets instead.
    def test_logical_order(self):
        self.assertEqual(encode('S','2',[255,256],2,2,5,5),'02ff000001')
        self.assertEqual(encode('S','b2',[b'\0\xff',b'\1\0'],2,2,5,5),'0200ff0100')
        self.assertEqual(encode('S','b2',[b'\xff\0',b'\0\1'],2,2,5,5),'noncanonical')

    # Duplicate keys are invalid even with different values; descending/equal values beside distinct keys are valid.
    def test_unique_keys(self):
        self.assertEqual(encode('M','nn',[(1,7),(1,8)],2,2,9,0),'noncanonical')
        self.assertEqual(encode('M','nn',[(1,8),(2,8)],2,2,9,9),'0201080208')
        self.assertEqual(decode('S','n',0,2,9,b'\2\2\1'),'noncanonical')

    # Empty and zero-width singleton collections retain distinct logical cardinalities despite an empty fixed payload.
    def test_zero_width(self):
        self.assertEqual(wire('F','0',[0]),b'')
        self.assertEqual(decode('F','0',1,1,0,b''),'0 1 0 - 01')
        self.assertEqual(decode('S','0',0,2,1,b'\2'),'noncanonical')
        self.assertEqual(decode('M','zz',0,1,1,b'\1'),'1 1 0/0 01')

    # Prefix framing, count policy and whole-source validation precede output sizing or initialized ownership.
    def test_precedence(self):
        self.assertEqual(decode('S','n',0,0,0,b'\x80\0'),'noncanonical')
        self.assertEqual(decode('S','n',0,0,0,b'\1'),'limitexceeded')
        self.assertEqual(decode('F','0',MAX,MAX,MAX,b''),'lengthoverflow')
        self.assertEqual(encode('F','1',[0],2,0,0,0),'invalidcount')
        self.assertEqual(encode('M','21',[(0,1),(1,256)],2,2,32,0),'valueoutofrange')

    # Count and scalar framing overhead consume the parent byte budget separately from actual output capacity.
    def test_byte_budget(self):
        self.assertEqual(encode('S','n',[128],1,1,2,9),'limitexceeded')
        self.assertEqual(encode('S','n',[128],1,1,3,2),'outputtoosmall')
        self.assertEqual(decode('S','n',0,1,3,b'\1\x80'),'truncated')
        self.assertEqual(decode('M','nn',0,1,9,b'\1\1\x80\0'),'noncanonical')


# Imports expose only references and never compile native binaries or alter upstream vectors.
if __name__=='__main__':
    unittest.main(verbosity=2)
